// ── Semantic entity diffing ───────────────────────────────────────────────────

/// Convert a `diffcore_core::git::FileDiff` into a `sem_core::git::types::FileChange`.
///
/// `FileDiff` has a `Copied` status that sem-core's `FileStatus` does not model;
/// we map it to `Modified` since the content exists on both sides.
pub(crate) fn to_sem_file_change(diff: &diffcore_core::git::FileDiff) -> sem_core::git::types::FileChange {
    use diffcore_core::git::FileStatus as DcStatus;
    use sem_core::git::types::{FileChange as SemFile, FileStatus as SemStatus};
    SemFile {
        file_path: diff.path().to_string(),
        old_file_path: if matches!(diff.status, DcStatus::Renamed) {
            diff.old_path.clone()
        } else {
            None
        },
        status: match diff.status {
            DcStatus::Added => SemStatus::Added,
            DcStatus::Deleted => SemStatus::Deleted,
            DcStatus::Renamed => SemStatus::Renamed,
            DcStatus::Copied | DcStatus::Modified => SemStatus::Modified,
        },
        before_content: diff.old_content.clone(),
        after_content: diff.new_content.clone(),
    }
}

/// Get semantic entity-level changes from the cached diff.
///
/// Reuses the `FileDiff` list already stored in `AppState::last_diff` — no second git
/// round trip. The heavy tree-sitter work is offloaded to a blocking thread pool so
/// the async runtime is not starved.
#[tauri::command]
pub async fn get_sem_entities(
    repo_path: String,
    base: Option<String>,
    state: tauri::State<'_, AppState>,
) -> Result<Vec<sem_core::model::change::SemanticChange>, CommandError> {
    use sem_core::parser::differ::compute_semantic_diff;
    use sem_core::parser::plugins::create_default_registry;

    let file_changes: Vec<sem_core::git::types::FileChange> = {
        let guard = state
            .last_diff
            .lock()
            .map_err(|_| CommandError::Analysis("lock poisoned".into()))?;
        let canonical = std::fs::canonicalize(&repo_path).ok();
        match guard.as_ref().filter(|c| {
            canonical
                .as_ref()
                .map_or(false, |rp| &c.repo_path == rp)
                && c.base == base
        }) {
            Some(cached) => cached
                .diff_result
                .files
                .iter()
                .map(to_sem_file_change)
                .collect(),
            None => {
                return Err(CommandError::Analysis(
                    "no cached diff — run analyze first".into(),
                ))
            }
        }
    };

    tauri::async_runtime::spawn_blocking(move || {
        let registry = create_default_registry();
        let result = compute_semantic_diff(&file_changes, &registry, None, None);
        Ok(result.changes)
    })
    .await
    .map_err(|e| CommandError::Analysis(format!("task join: {e}")))?
}

