    Interface,
    TypeAlias,
    Constant,
    Module,
}

/// Edge types in the symbol graph.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum EdgeType {
    Imports,
    Calls,
    Extends,
    Instantiates,
    Reads,
    Writes,
    Emits,
    Handles,
}

/// An edge in the flow graph between two symbols.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FlowEdge {
