    pub hunks: u32,
}

/// A changed file within a flow group.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FileChange {
    pub path: String,
    pub flow_position: u32,
    pub role: FileRole,
    pub changes: ChangeStats,
