/// Build a filesystem-safe context slug from compare settings.
pub fn context_slug(compare: &SessionCompare) -> String {
    let mode = compare.resolved_comparison_mode();
    let base = compare.resolved_base_ref().unwrap_or("-");
    let head = compare.resolved_head_ref().unwrap_or("-");
    let canonical = format!("mode={mode}\nbase={base}\nhead={head}");
    let digest = Sha256::digest(canonical.as_bytes());
    hex::encode(digest)[..16].to_string()
}

/// Allocate the next session ID for a compare context.
pub fn allocate_session_id(repo_workdir: &Path, compare: &SessionCompare) -> Result<String, String> {
    let slug = context_slug(compare);
    let root = repo_workdir.join(".diffcore");
    std::fs::create_dir_all(&root)
        .map_err(|e| format!("Failed to create .diffcore directory: {}", e))?;

    let prefix = format!("{slug}--");
    let mut max_index = 0u32;
    let read_dir = std::fs::read_dir(&root)
        .map_err(|e| format!("Failed to read .diffcore directory: {}", e))?;
    for entry in read_dir {
        let entry = entry.map_err(|e| format!("Failed to read .diffcore entry: {}", e))?;
        let file_type = entry
            .file_type()
            .map_err(|e| format!("Failed to inspect .diffcore entry: {}", e))?;
        if !file_type.is_dir() {
            continue;
        }
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if !name.starts_with(&prefix) {
            continue;
        }
        let Some(index_str) = name.strip_prefix(&prefix) else {
            continue;
        };
        if let Ok(index) = index_str.parse::<u32>() {
            max_index = max_index.max(index);
        }
    }

    Ok(format!("{slug}--{}", max_index + 1))
}

