    let json = serde_json::to_string_pretty(value)
        .map_err(|e| format!("Failed to serialize JSON: {}", e))?;
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|e| format!("System clock error: {}", e))?
        .as_nanos();
    let tmp_name = format!(
        ".{}.{}.{}.tmp",
        path.file_name().and_then(|n| n.to_str()).unwrap_or("session"),
        std::process::id(),
        nanos
    );
    let tmp_path = path
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .join(tmp_name);
    std::fs::write(&tmp_path, json).map_err(|e| format!("Failed to write temp file: {}", e))?;
    std::fs::rename(&tmp_path, path).map_err(|e| format!("Failed to atomically replace file: {}", e))
}

