/// Collect all graph edges where both endpoints belong to files in the group.
pub(super) fn collect_internal_edges(
    graph: &SymbolGraph,
    group_files: &HashSet<&str>,
) -> Vec<FlowEdge> {
    let mut edges: Vec<FlowEdge> = graph
        .edges()
        .into_iter()
        .filter_map(|(from, to, edge_type)| {
            let from_file = graph.get_symbol(from).map(|s| s.file.as_str())?;
            let to_file = graph.get_symbol(to).map(|s| s.file.as_str())?;
            if group_files.contains(from_file) && group_files.contains(to_file) {
                Some(FlowEdge {
                    from: from.to_string(),
                    to: to.to_string(),
                    edge_type: edge_type.clone(),
                })
            } else {
                None
            }
        })
        .collect();

    // Sort for deterministic output.
    edges.sort_by(|a, b| a.from.cmp(&b.from).then_with(|| a.to.cmp(&b.to)));
    edges
}

/// Generate a human-readable name for a flow group based on its entrypoint.
pub(super) fn generate_group_name(ep: &Entrypoint) -> String {
    // Extract file basename without extension
    let basename = ep
        .file
        .rsplit('/')
        .next()
        .unwrap_or(&ep.file)
        .rsplit('.')
        .last()
        .unwrap_or(&ep.file);

    // Use symbol if it differs from the file basename; otherwise just use basename
    let label = if ep.symbol == basename || ep.symbol == "default" || ep.symbol == "module" {
        basename.to_string()
    } else {
        format!("{} ({})", ep.symbol, basename)
    };

    match ep.entrypoint_type {
        EntrypointType::HttpRoute => format!("{} route", label),
        EntrypointType::CliCommand => format!("{} CLI", label),
        EntrypointType::QueueConsumer => format!("{} consumer", label),
        EntrypointType::CronJob => format!("{} scheduled", label),
        EntrypointType::ReactPage => format!("{} page", label),
        EntrypointType::TestFile => format!("{} test", label),
        EntrypointType::EventHandler => format!("{} event", label),
        EntrypointType::EffectService => format!("{} Effect service", label),
    }
}

pub fn build_analysis_output(
    diff_result: &DiffResult,
    diff_source: DiffSource,
    parsed_files: &[ParsedFile],
    cluster_result: &ClusterResult,
    ranked_groups: &[RankedGroup],
) -> AnalysisOutput {
    // Detect languages from parsed files.
    let languages_detected: Vec<String> = {
        let mut langs: Vec<String> = parsed_files
            .iter()
            .map(|f| f.language)
            .collect::<HashSet<_>>()
            .into_iter()
            .filter(|l| *l != Language::Unknown)
            .map(|l| format!("{:?}", l).to_lowercase())
            .collect();
        langs.sort();
        langs
    };

    // Build diff stats lookup: file path → (additions, deletions, hunks)
    let diff_stats: std::collections::HashMap<&str, (u32, u32, u32)> = diff_result
        .files
        .iter()
        .map(|f| (f.path(), (f.additions, f.deletions, f.hunks.len() as u32)))
        .collect();

    // Apply ranking to groups: update risk_score, review_order, and enrich change stats.
    let groups: Vec<FlowGroup> = cluster_result
        .groups
        .iter()
        .map(|group| {
            let ranked = ranked_groups.iter().find(|r| r.group_id == group.id);
            let files = group
                .files
                .iter()
                .map(|fc| {
                    if let Some(&(additions, deletions, hunks)) = diff_stats.get(fc.path.as_str()) {
                        FileChange {
                            changes: ChangeStats {
                                additions,
                                deletions,
                                hunks,
                            },
                            ..fc.clone()
                        }
                    } else {
                        fc.clone()
                    }
                })
                .collect();
            FlowGroup {
                risk_score: ranked.map_or(group.risk_score, |r| r.composite_score),
                review_order: ranked.map_or(group.review_order, |r| r.review_order),
                files,
                ..group.clone()
            }
        })
        .collect();

    let frameworks_detected = crate::flow::detect_frameworks(parsed_files);

    let summary = AnalysisSummary {
        total_files_changed: diff_result.files.len() as u32,
        total_groups: groups.len() as u32,
        languages_detected,
        frameworks_detected,
    };

    // Enrich the infra group with per-file change stats using the same diff_stats
    // map already built above. `files` (bare paths) is kept for JSON backward
    // compatibility; `file_changes` carries the enriched data for UI consumers.
    let infrastructure_group = cluster_result.infrastructure.as_ref().map(|ig| {
        let make_fc = |path: &String| -> FileChange {
            let (additions, deletions, hunks) = diff_stats.get(path.as_str()).copied().unwrap_or((0, 0, 0));
            FileChange {
                path: path.clone(),
                flow_position: 0,
                role: FileRole::Infrastructure,
                changes: ChangeStats {
                    additions,
                    deletions,
                    hunks,
                },
                symbols_changed: vec![],
            }
        };
        let file_changes = ig.files.iter().map(&make_fc).collect();
        let sub_groups = ig
            .sub_groups
            .iter()
            .map(|sg| InfraSubGroup {
                file_changes: sg.files.iter().map(&make_fc).collect(),
                ..sg.clone()
            })
            .collect();
        InfrastructureGroup {
            file_changes,
            sub_groups,
            ..ig.clone()
        }
    });

    AnalysisOutput {
        version: "1.0.0".to_string(),
        diff_source,
        summary,
        groups,
        infrastructure_group,
        annotations: None,
    }
}

